head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDBNF45000";
scwin.mode = "INFO";            // INFO: 담당자 정보 수정, CHANGE: 담당자 변경 (원본 hidden addNew "" / "ADD")
scwin.selectedRow = -1;         // 목록에서 고른 행 (원본 tr.on)
scwin.bfBdchrgTpCd = "";        // 변경 전 담당자구분 — 담당자 변경 때 구분을 바꾸지 못하게 (원본 hidden bf_bdchrg_tp_cd)
scwin.isSaving = false;        // 저장 중 — [수정] 연타 방지(udcSaver.save 는 sbm 중복 실행 방지를 타지 않는다)
// 첨부 서류 3종 — 행 순서가 서류 구분이다(명세 dlt_files 에 서류 코드 열이 없음 — 결과서 §10 #4)
scwin.FILE_DOCS = [
    { docCd : "04", name : "상장채권 신고권한 위임장" },
    { docCd : "05", name : "개인정보동의서" },
    { docCd : "06", name : "재직증명서" }
];

// 서식다운로드 — 원본 fileDownForm (contnId, cmNotiClssCd 4)
scwin.DOC_FORMS = {
    1 : { contnId : "122", name : "상장채권 신고권한 위임장" },
    2 : { contnId : "123", name : "개인정보동의서" }
};

// 원본 : ULDBNF45000.jsp (채권신고담당자 정보변경 — 대외 메인 화면)
/*
 * 화면 동작
 *  - 로그인 회사(발행기관)의 채권신고담당자(정·부) 목록을 보여 주고, 행을 고르면 상세를 입력란에 채운다.
 *  - [수정]: 정보 수정 모드면 연락처 정보를 수정(mgrInfo-update), 담당자 변경 모드면 새 담당자 + 서류 3종 첨부로 변경(mgrUpdate-proc).
 *  - [담당자 변경]: 고른 담당자를 다른 사람으로 바꾸는 모드로 전환(이름·소속기관 입력 가능, 첨부 영역 표시).
 * 업무 분석 : conversion/gfm-front/ui/ULDBNF45000/ULDBNF45000.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 26
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 26
 * @description 로딩 — 발행기관 정보 → 입력란·첨부 초기화 → 담당자 목록 조회. (원본 $(document).ready + JSP 서버 렌더링 — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 발행기관 정보 — 원본은 JSP companyInfoVO
    // TODO: 발행기관코드·명, 서류 면제 여부(bdchrgRegNoFileInstYn)의 출처 확정 (§10 #1·#2)
    dma_page.set("isurCd", $c.session.getUserInfo("isurCd") ?? "");
    dma_page.set("comNm", $c.session.getUserInfo("comNm") ?? "");
    dma_page.set("fileExemptYn", $c.session.getUserInfo("bdchrgRegNoFileInstYn") ?? "");
    txt_isurCd.setValue(dma_page.get("isurCd"));
    txt_comNm.setValue(dma_page.get("comNm"));

    // 2) 입력란·첨부 초기화 — 행 클릭·저장 뒤에도 같은 로직이라 5구역 함수로
    scwin.resetForm();

    // 3) 담당자 목록 조회 — 원본은 JSP 가 서버에서 그렸다(※TO-BE 통신)
    await scwin.searchList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.grd_bdchrgList_oncellclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 목록 행 클릭 — 상세 조회. (원본 tr onclick="focus_tr(this)" — §4)
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @returns
 * @hidden N
 */
scwin.grd_bdchrgList_oncellclick = async function (row, col) {
    try {
        await scwin.selectDtl(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.grd_bdchrgList_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_chgBdchrg_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 변경 버튼 클릭. (원본 fn_AddNewBdchrg — §6.2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_chgBdchrg_onclick = async function (e) {
    try {
        await scwin.startChange();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_chgBdchrg_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_update_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 버튼 클릭 — 모드에 따라 정보 수정 또는 담당자 변경. (원본 fn_Update — §6.1·§6.2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_update_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_findFile1_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 상장채권 신고권한 위임장 찾아보기 (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_findFile1_onclick = async function (e) {
    try {
        scwin.attachFile(0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_findFile1_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_findFile2_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 개인정보동의서 찾아보기 (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_findFile2_onclick = async function (e) {
    try {
        scwin.attachFile(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_findFile2_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_findFile3_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 재직증명서 찾아보기 (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_findFile3_onclick = async function (e) {
    try {
        scwin.attachFile(2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_findFile3_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_docDown1_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 상장채권 신고권한 위임장 서식다운로드 (§6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_docDown1_onclick = async function (e) {
    try {
        await scwin.downloadDoc(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_docDown1_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_docDown2_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 개인정보동의서 서식다운로드 (§6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_docDown2_onclick = async function (e) {
    try {
        await scwin.downloadDoc(2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.btn_docDown2_onclick" });
    }
};

/**
 * @method
 * @name scwin.dlt_files_oncelldatachange
 * @author Inswave
 * @date 2026. 10. 26
 * @description 첨부 목록이 바뀌면(UDC 파일 선택) 서류별 파일명 칸을 다시 채운다. (원본 fn_getFileNm — §6.3)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.dlt_files_oncelldatachange = async function (info) {
    try {
        scwin.showFileNames();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNF45000.dlt_files_oncelldatachange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 목록 조회. (명세 bndClaimMgr-select — §5.1)
 * @returns
 * @hidden N
 */
scwin.searchList = async function () {
    scwin.selectedRow = -1;
    dma_searchList.setEmptyValue();
    // TODO: 목록은 isurCd 만 채운다 — chrgId·bdchrgTpCd 를 비워도 되는지 확인 (§10 #6)
    dma_searchList.set("isurCd", dma_page.get("isurCd"));

    const sbmOptions = {
        id : "sbm_searchList",
        method : "get",
        action : "/api/bonds/accountMgt/bndClaimMgrUpdate/bndClaimMgr-select",
        target : "dlt_searchList=body",
        gridview : "grd_bdchrgList|message",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, dma_searchList.getJSON());
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) {
        await $c.win.alert("현재 서버에서 채권신고담당자 목록을 가져올 수 없습니다. 관리자에게 문의하세요.");
    }
};

/**
 * @method
 * @name scwin.selectDtl
 * @author Inswave
 * @date 2026. 10. 26
 * @description 고른 담당자의 상세를 조회해 입력란에 나눠 채운다(정보 수정 모드). (원본 focus_tr + fn_SelectBdchrgDtlInfo 동기 $.ajax — §5.2)
 * @param {Number} row 목록 행 index
 * @returns
 * @hidden N
 */
scwin.selectDtl = async function (row) {
    scwin.resetForm();
    scwin.selectedRow = row;
    scwin.bfBdchrgTpCd = "";
    dma_form.set("bdchrgTpCd", dlt_searchList.getCellData(row, "bdchrgTpCd"));

    dma_searchDtlReq.setEmptyValue();
    dma_searchDtlReq.set("isurCd", dlt_searchList.getCellData(row, "isurCd") || dma_page.get("isurCd"));
    dma_searchDtlReq.set("chrgId", dlt_searchList.getCellData(row, "chrgId"));
    dma_searchDtlReq.set("bdchrgTpCd", dlt_searchList.getCellData(row, "bdchrgTpCd"));

    const sbmOptions = {
        id : "sbm_selectDtl",
        method : "get",
        action : "/api/bonds/accountMgt/bndClaimMgrUpdate/bndClaimMgrDtl-select",
        target : "dma_searchDtlRes=body",
        isProcessMsg : false
    };

    // 빠르게 다른 행을 누르면 마지막 행 기준(취소된 요청의 reject 는 handleError 가 무시)
    const result = await $c.sbm.executeDynamic(sbmOptions, dma_searchDtlReq.getJSON(), null, { onDuplicate : "abort" });
    if (result?.skipped) return;

    if (!result.responseJSON?.success) {
        scwin.selectedRow = -1;
        await $c.win.alert("현재 서버에서 채권신고담당자 정보를 가져올 수 없습니다. 관리자에게 문의하세요.");
        return;
    }

    dma_form.set("bdchrgTpCd", dma_searchDtlRes.get("bdchrgTpCd"));
    dma_form.set("chrgNm", dma_searchDtlRes.get("chrgNm"));
    dma_form.set("jobposNm", dma_searchDtlRes.get("jobposNm"));
    dma_form.set("belngInstNm", dma_searchDtlRes.get("belngInstNm"));
    dma_form.set("belngDepNm", dma_searchDtlRes.get("belngDepNm"));

    // 원본 setTelNo·setCellphoneNo·setEmail·setFaxNo — 국번 "00" 은 빈칸으로
    scwin.splitTo("telNo", dma_searchDtlRes.get("telNo"), "-", true);
    scwin.splitTo("cellphoneNo", dma_searchDtlRes.get("cellphoneNo"), "-", false);
    scwin.splitTo("email", dma_searchDtlRes.get("email"), "@", false);
    scwin.splitTo("faxNo", dma_searchDtlRes.get("faxNo"), "-", true);

    scwin.bfBdchrgTpCd = dma_searchDtlRes.get("bdchrgTpCd");
};

/**
 * @method
 * @name scwin.updateInfo
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 정보 수정. 성공하면 완료 안내 후 목록을 다시 읽는다. (원본 폼 submit updateBdchrgInfo — 명세 mgrInfo-update §5.3)
 * @returns
 * @hidden N
 */
scwin.updateInfo = async function () {
    scwin.buildRequest();

    const sbmOptions = {
        id : "sbm_updateInfo",
        method : "post",
        action : "/api/bonds/accountMgt/bndClaimMgrUpdate/mgrInfo-update",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, dma_mgrInfoUpdate.getJSON());
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        // TODO: 실패 문구 확정 — 원본은 실패 안내 없음 (§10 #7)
        await $c.win.alert($c.data.getMessage("com_complete_0151", "담당자 정보 수정"));
        return;
    }

    await scwin.afterSave();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.changeBdchrg
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 변경 — 전문과 첨부 3종을 UDC 로 한 번에 보낸다. (원본 폼 submit changeBdchrg + attachFiles — 명세 mgrUpdate-proc §5.4)
 * @returns
 * @hidden N
 */
scwin.changeBdchrg = async function () {
    scwin.buildRequest();

    // TODO: 서버가 받는 파트 이름(dataMapId·dataListId)과 첨부의 서류 구분 전달 방법 확정 (§10 #4)
    await udcSaver.save({
        dataMap : dma_mgrInfoUpdate,
        dataMapId : "dto",
        dataList : dlt_files,
        dataListId : "fileList",
        saveUrl : $c.sbm.getContextPath() + "/api/bonds/accountMgt/bndClaimMgrUpdate/mgrUpdate-proc",     // UDC 는 fetch 직접 호출 — contextRoot 를 붙인다
        // onSuccess 는 HTTP 200 이면 처리 결과와 무관하게 await 없이 불린다 — 결과 판단은 await 되는 onAfterSave 에서
        onAfterSave : async function (res) {
            if (!res?.success) {
                // TODO: 실패 문구 확정 — 원본은 실패 안내 없음 (§10 #7)
                await $c.win.alert($c.data.getMessage("com_complete_0151", "담당자 변경"));
                return;
            }
            await scwin.afterSave();
        },
        onError : async function (ex) {
            await $c.exception.handleError(ex, { context : "ULDBNF45000.changeBdchrg" });
        }
    });
};

/**
 * @method
 * @name scwin.resetForm
 * @author Inswave
 * @date 2026. 10. 26
 * @description 입력란·첨부 초기화 — 정보 수정 모드, 이름·소속기관 읽기전용, 첨부 영역 숨김. (원본 initBdchrgInfo + initFileList — §6.5)
 * 담당자구분은 비우지 않는다 — 원본도 선택값이 남고(§8 #1) 담당자 변경 검증이 그 값을 전제로 한다(§6.2).
 * @returns
 * @hidden N
 */
scwin.resetForm = function () {
    const bdchrgTpCd = dma_form.get("bdchrgTpCd");
    dma_form.setEmptyValue();
    dma_form.set("bdchrgTpCd", bdchrgTpCd);

    ipt_chrgNm.setReadOnly(true);
    ipt_belngInstNm.setReadOnly(true);
    scwin.mode = "INFO";

    grp_fileList.hide();
    scwin.initFiles();
};

/**
 * @method
 * @name scwin.initFiles
 * @author Inswave
 * @date 2026. 10. 26
 * @description 첨부 서류 3행을 비운 상태로 다시 만든다. (원본 initFileList — §6.3)
 * @returns
 * @hidden N
 */
scwin.initFiles = function () {
    udcSaver.clearFileMap();
    dlt_files.setJSON(scwin.FILE_DOCS.map((doc, i) => ({
        id : i + 1, uid : "", empNo : "", empName : "", fileName : "", fileSize : 0, fileChanged : ""
    })));
    scwin.showFileNames();
};

/**
 * @method
 * @name scwin.showFileNames
 * @author Inswave
 * @date 2026. 10. 26
 * @description 첨부 목록의 파일명을 서류별 파일명 칸(ipt_fileNm1~3)에 표시한다.
 * @returns
 * @hidden N
 */
scwin.showFileNames = function () {
    [ipt_fileNm1, ipt_fileNm2, ipt_fileNm3].forEach((comp, i) => {
        comp.setValue(i < dlt_files.getRowCount() ? (dlt_files.getCellData(i, "fileName") ?? "") : "");
    });
};

/**
 * @method
 * @name scwin.attachFile
 * @author Inswave
 * @date 2026. 10. 26
 * @description 서류 행에 파일을 첨부한다 — UDC 파일 선택 다이얼로그. (원본 input type="file" + fn_getFileNm — §6.3)
 * @param {Number} row 서류 행 index (0 위임장, 1 개인정보동의서, 2 재직증명서)
 * @returns
 * @hidden N
 */
scwin.attachFile = function (row) {
    // uid 는 UDC 파일 맵의 키 — 다시 고를 때 새로 만들면 이전 파일이 맵에 남아 함께 전송된다
    if ($c.util.isEmpty(dlt_files.getCellData(row, "uid"))) {
        dlt_files.setCellData(row, "uid", "BDCHRG_" + scwin.FILE_DOCS[row].docCd + "_" + new Date().getTime());
    }
    udcSaver.attachFile(row, dlt_files);
};

/**
 * @method
 * @name scwin.downloadDoc
 * @author Inswave
 * @date 2026. 10. 26
 * @description 서류 서식을 내려받는다. (원본 fn_downloadDoc + fileDownForm — §6.4)
 * @param {Number} no 서식 번호 (1 위임장, 2 개인정보동의서)
 * @returns
 * @hidden N
 */
scwin.downloadDoc = async function (no) {
    const doc = scwin.DOC_FORMS[no];
    if (!await $c.win.confirm(doc.name + " 다운로드 하시겠습니까?")) return;

    // TODO: 신규 API 명세에 서식다운로드가 없다 — 원본 /main/notice.do?method=downloadFile(contnId, cmNotiClssCd 4) 대체 경로 확정 (§10 #5)
    await $c.win.alert(doc.name + " 서식 다운로드 경로 확정 전(TODO)");
};

/**
 * @method
 * @name scwin.startChange
 * @author Inswave
 * @date 2026. 10. 26
 * @description 담당자 변경 모드로 전환 — 확인 후 입력란·첨부를 비우고 이름·소속기관을 입력 가능하게, 첨부 영역을 보인다. (원본 fn_AddNewBdchrg — §6.2)
 * @returns
 * @hidden N
 */
scwin.startChange = async function () {
    const row = scwin.selectedRow;
    if (row < 0) {
        await $c.win.alert("변경 대상 담당자를 선택하세요.");
        return;
    }

    const name = dlt_searchList.getCellData(row, "chrgNm");
    if (!await $c.win.confirm("[" + name + "] 을(를) 다른 사람으로 변경하시겠습니까?")) return;

    scwin.resetForm();
    ipt_chrgNm.setReadOnly(false);
    ipt_belngInstNm.setReadOnly(false);
    grp_fileList.show("");
    scwin.mode = "CHANGE";
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 — 검증 → 확인 → 정보 수정(INFO) 또는 담당자 변경(CHANGE). 저장 중에는 다시 누를 수 없다. (원본 fn_Update — §1.4 업무 3·4)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    if (scwin.isSaving) return;
    scwin.isSaving = true;
    try {
        if (!await scwin.validate()) return;
        if (!await $c.win.confirm("변경하시겠습니까?")) return;

        if (scwin.mode === "CHANGE") {
            await scwin.changeBdchrg();
        } else {
            await scwin.updateInfo();
        }
    } finally {
        scwin.isSaving = false;
    }
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 26
 * @description 입력 검증 — 필수 항목(공통 검증) 후, 담당자 변경 모드면 담당자구분 유지·필수 첨부를 본다. (원본 fn_chkData — §6.1·§6.2)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    // 원본처럼 이름·직책·소속기관·소속부서는 앞뒤 공백을 지우고 검사한다(공통 검증은 trim 하지 않는다 — §10 #10)
    ["chrgNm", "jobposNm", "belngInstNm", "belngDepNm"].forEach((key) => {
        dma_form.set(key, String(dma_form.get(key) ?? "").trim());
    });
    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            ipt_chrgNm : { required : true, maxLengthB : 40, name : "이름" },
            ipt_jobposNm : { required : true, name : "직책" },
            ipt_belngInstNm : { required : true, name : "소속기관" },
            ipt_belngDepNm : { required : true, name : "소속부서" },
            ipt_telNo2 : { required : true, name : "전화번호" },
            ipt_telNo3 : { required : true, name : "전화번호" },
            ipt_cellphoneNo1 : { required : true, name : "휴대전화번호" },
            ipt_cellphoneNo2 : { required : true, name : "휴대전화번호" },
            ipt_cellphoneNo3 : { required : true, name : "휴대전화번호" },
            ipt_email1 : { required : true, maxLengthB : 40, name : "이메일" },
            ipt_email2 : { required : true, maxLengthB : 40, name : "이메일" }
        }
    };
    if (!await $c.validate.validateDataCollect(grp_dtlInfo, options)) return false;

    if (scwin.mode !== "CHANGE") return true;

    // 담당자를 다른 사람으로 바꿀 때는 담당자구분을 바꿀 수 없다(원본 endForm 오타로 되돌리기 실패 — §8 #2 고침).
    if (dma_form.get("bdchrgTpCd") !== scwin.bfBdchrgTpCd) {
        await $c.win.alert("담당자구분은 변경할 수 없습니다.");
        dma_form.set("bdchrgTpCd", scwin.bfBdchrgTpCd);
        return false;
    }

    // 서류 면제(국고채 대행 한국은행·정부·지자체)가 아니면 서류 3종 필수
    if (dma_page.get("fileExemptYn") !== "Y") {
        const fileComps = [ipt_fileNm1, ipt_fileNm2, ipt_fileNm3];
        for (let i = 0; i < scwin.FILE_DOCS.length; i++) {
            if ($c.util.isEmpty(dlt_files.getCellData(i, "fileName"))) {
                await $c.win.alert("필수 첨부파일을 입력하세요.");
                fileComps[i].focus();
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.splitTo
 * @author Inswave
 * @date 2026. 10. 26
 * @description 합쳐진 값(전화 "02-1234-5678", 이메일 "a@b")을 입력란 칸(dma_form.{prefix}1~)에 나눠 채운다. 조각 수가 맞지 않으면 비운다.
 * (원본 setTelNo·setCellphoneNo·setEmail·setFaxNo)
 * @param {String} prefix dma_form 키 접두(telNo·cellphoneNo·email·faxNo)
 * @param {String} value 합쳐진 값
 * @param {String} sep 구분자("-" 또는 "@")
 * @param {Boolean} blankZeroArea 첫 칸이 "00"(국번 미입력 저장값)이면 빈칸으로
 * @returns
 * @hidden N
 */
scwin.splitTo = function (prefix, value, sep, blankZeroArea) {
    const count = (sep === "@") ? 2 : 3;
    const parts = $c.util.isEmpty(value) ? [] : String(value).split(sep);
    if (parts.length !== count) return;

    parts.forEach((part, i) => {
        dma_form.set(prefix + (i + 1), (i === 0 && blankZeroArea && part === "00") ? "" : part);
    });
};

/**
 * @method
 * @name scwin.joinContacts
 * @author Inswave
 * @date 2026. 10. 26
 * @description 입력란 칸을 전문 값으로 합친다 — 국번이 비면 "00", 팩스는 한 칸이라도 있을 때만. (원본 setCellphoneNoEtc — §6.1)
 * @returns {Object} { telNo, cellphoneNo, email, faxNo }
 * @hidden N
 */
scwin.joinContacts = function () {
    const f = (key) => dma_form.get(key) ?? "";
    const telArea = $c.util.isEmpty(f("telNo1")) ? "00" : f("telNo1");
    const hasFax = !$c.util.isEmpty(f("faxNo1")) || !$c.util.isEmpty(f("faxNo2")) || !$c.util.isEmpty(f("faxNo3"));

    return {
        telNo : telArea + "-" + f("telNo2") + "-" + f("telNo3"),
        cellphoneNo : f("cellphoneNo1") + "-" + f("cellphoneNo2") + "-" + f("cellphoneNo3"),
        email : f("email1") + "@" + f("email2"),
        faxNo : hasFax ? (f("faxNo1") + "-" + f("faxNo2") + "-" + f("faxNo3")) : ""
    };
};

/**
 * @method
 * @name scwin.buildRequest
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장 전문(명세 dma_mgrInfoUpdate)을 채운다 — 정보 수정·담당자 변경 공통. (원본 SendForm 필드 — §5.3)
 * @returns
 * @hidden N
 */
scwin.buildRequest = function () {
    const row = scwin.selectedRow;
    const contacts = scwin.joinContacts();

    dma_mgrInfoUpdate.setEmptyValue();
    // TODO: bndApplId·loginId·transtrId·empNo·empNm·bdchrgApplTpCd·bdchrgApplStatCd·applProcsContn·chrgUseYn·bdchrgTpNm 은
    //       원본이 보내지 않던 값 — 화면이 채울지 서버가 채울지 확인 (§10 #3)
    dma_mgrInfoUpdate.setJSON({
        chrgId : (row >= 0) ? dlt_searchList.getCellData(row, "chrgId") : "",
        isurCd : dma_page.get("isurCd"),
        bdchrgTpCd : dma_form.get("bdchrgTpCd"),
        bfBdchrgTpCd : scwin.bfBdchrgTpCd,
        chrgNm : dma_form.get("chrgNm"),
        jobposNm : dma_form.get("jobposNm"),
        belngInstNm : dma_form.get("belngInstNm"),
        belngDepNm : dma_form.get("belngDepNm"),
        telNo : contacts.telNo,
        cellphoneNo : contacts.cellphoneNo,     // TODO: 명세는 "암호화" — 평문 전송 가정 (§10 #9)
        email : contacts.email,
        faxNo : contacts.faxNo
    });
};

/**
 * @method
 * @name scwin.afterSave
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장 성공 뒤 — 완료 안내, 입력란 초기화, 목록 재조회. (원본 modifyComplete=Y 페이지 재요청 — §1.1)
 * @returns
 * @hidden N
 */
scwin.afterSave = async function () {
    await $c.win.alert("요청하신 작업을 완료하였습니다.");
    scwin.resetForm();
    await scwin.searchList();
};
